/// Drop a trailing " — <digits> due" from an action title.
///
/// The ported `brief` builds its titles in MINOR UNITS, faithfully to the TypeScript, which is right
/// for a JSON consumer and actively misleading in a terminal: "6000 due" printed beside a formatted
/// "60.00" reads as two different numbers a hundred times apart. The amount already has its own
/// column here, so the renderer drops the duplicate rather than the module changing units and
/// diverging from the other kit.
pub(crate) fn trim_minor_suffix(title: &str) -> &str {
    let Some(cut) = title.rfind(" — ") else { return title };
    let tail = &title[cut + " — ".len()..];
    match tail.strip_suffix(" due") {
        Some(n) if !n.is_empty() && n.chars().all(|c| c.is_ascii_digit()) => &title[..cut],
        _ => title,
    }
}
